package org.chromium.chrome.browser; import org.chromium.chrome.browser.tab.Tab; public class ActivityTabProvider {public Tab tab; public ActivityTabTabObserver observer; public Tab get(){return tab;} public static class ActivityTabTabObserver {final ActivityTabProvider p; public ActivityTabTabObserver(ActivityTabProvider p,boolean trigger){this.p=p;p.observer=this;if(trigger)onObservingDifferentTab(p.tab);} protected void onObservingDifferentTab(Tab t){} public void onContentChanged(Tab t){} public void onDestroyed(Tab t){} public void destroy(){p.observer=null;} } public void change(Tab t){tab=t;if(observer!=null)observer.onObservingDifferentTab(t);} }
